from copy import deepcopy
from math import isfinite
from collections.abc import Mapping

GATES = (
    "catalog_visible", "tenant_ok", "region_ok", "data_boundary_ok",
    "quota_ok", "identity_ok", "network_ok", "marketplace_ok",
    "workload_evidence_ok",
)
EXACT_FIELDS = ("id", "publisher", "model", "version", "sku", "lifecycle")
SHAPES = {"standard", "provisioned", "managed_compute"}
PRODUCTION_LIFECYCLES = {"ga"}


def finite_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and isfinite(value)


def exact_string(value, field):
    if not isinstance(value, str) or not value or value != value.strip():
        raise ValueError(field + " must be a nonempty exact string without surrounding whitespace")


def string_list(value, field):
    if not isinstance(value, list) or not value:
        raise ValueError(field + " must be a nonempty list")
    seen = set()
    for item in value:
        exact_string(item, field + " item")
        if item in seen:
            raise ValueError(field + " contains a duplicate")
        seen.add(item)


def validate_option(option):
    if not isinstance(option, Mapping):
        raise ValueError("option must be an object")
    for field in EXACT_FIELDS:
        exact_string(option.get(field), field)
    shape = option.get("shape")
    if not isinstance(shape, str):
        raise ValueError("shape must be a string")
    if shape not in SHAPES:
        raise ValueError("unsupported deployment shape: " + shape)
    score = option.get("fit_score")
    if not finite_number(score) or not 0 <= score <= 1:
        raise ValueError("fit_score must be finite, numeric, not Boolean, and between 0 and 1")
    exact_string(option.get("route_scope"), "route_scope")
    exact_string(option.get("data_boundary"), "data_boundary")
    for gate in GATES:
        if not isinstance(option.get(gate), bool):
            raise ValueError("unknown or non-Boolean hard gate: " + gate)
    cost = option.get("cost")
    if not isinstance(cost, Mapping):
        raise ValueError("cost must be an object")
    status = cost.get("status")
    if status == "unknown":
        return
    if status != "reservation" or shape != "provisioned":
        raise ValueError("cost must be explicitly unknown or a provisioned reservation")
    rate = cost.get("reservation_usd_per_hour")
    hours = cost.get("reservation_hours")
    utilization = cost.get("utilization_fraction")
    if not finite_number(rate) or rate < 0:
        raise ValueError("reservation_usd_per_hour must be finite and nonnegative")
    if not finite_number(hours) or hours <= 0:
        raise ValueError("reservation_hours must be finite and positive")
    if not finite_number(utilization) or not 0 <= utilization <= 1:
        raise ValueError("utilization_fraction must be between 0 and 1")


def validate_case(case):
    if not isinstance(case, Mapping):
        raise ValueError("case must be an object")
    exact_string(case.get("name"), "case name")
    policy = case.get("policy")
    if not isinstance(policy, Mapping):
        raise ValueError("policy must be an object")
    threshold = policy.get("min_fit_score")
    if not finite_number(threshold) or not 0 <= threshold <= 1:
        raise ValueError("min_fit_score must be finite, numeric, not Boolean, and between 0 and 1")
    string_list(policy.get("allowed_route_scopes"), "allowed_route_scopes")
    string_list(policy.get("allowed_data_boundaries"), "allowed_data_boundaries")
    options = case.get("options")
    if not isinstance(options, list) or not options:
        raise ValueError("options must be a nonempty list")
    seen = set()
    for option in options:
        validate_option(option)
        option_id = option["id"]
        if option_id in seen:
            raise ValueError("duplicate option id: " + option_id)
        seen.add(option_id)


def reservation_total(option):
    cost = option["cost"]
    if cost["status"] != "reservation":
        return None
    return cost["reservation_usd_per_hour"] * cost["reservation_hours"]


def decide(case):
    try:
        validate_case(case)
    except ValueError as error:
        name = case.get("name") if isinstance(case, Mapping) and isinstance(case.get("name"), str) else "UNKNOWN"
        return name + ": REFUSE_ALL (CONTROL_ERROR: " + str(error) + ")"

    policy = case["policy"]
    rejected = {}
    eligible = []
    for option in case["options"]:
        reasons = []
        for gate in GATES:
            if option[gate] is False:
                reasons.append(gate + " is false")
        if option["lifecycle"] not in PRODUCTION_LIFECYCLES:
            reasons.append("lifecycle " + option["lifecycle"] + " is not allowed by production policy")
        if option["route_scope"] not in policy["allowed_route_scopes"]:
            reasons.append("route_scope " + option["route_scope"] + " is not allowed by case policy")
        if option["data_boundary"] not in policy["allowed_data_boundaries"]:
            reasons.append("data_boundary " + option["data_boundary"] + " is not allowed by case policy")
        if option["fit_score"] < policy["min_fit_score"]:
            reasons.append("fit_score {:.2f} is below trusted threshold {:.2f}".format(
                option["fit_score"], policy["min_fit_score"]
            ))
        if reasons:
            rejected[option["id"]] = reasons
        else:
            eligible.append(option)

    if not eligible:
        lines = [case["name"] + ": REFUSE_ALL"]
        for option in case["options"]:
            lines.append("  " + option["id"] + ": REJECT " + "; ".join(rejected[option["id"]]))
        return "\n".join(lines)

    winner = max(eligible, key=lambda item: (item["fit_score"], item["id"]))
    lines = [case["name"] + ": CONDITIONAL_RECOMMENDATION " + winner["id"]]
    for option in case["options"]:
        if option["id"] in rejected:
            lines.append("  " + option["id"] + ": REJECT " + "; ".join(rejected[option["id"]]))
        elif option["id"] != winner["id"]:
            lines.append("  " + option["id"] + ": NOT_SELECTED fit_score {:.2f} is below winner {:.2f}".format(
                option["fit_score"], winner["fit_score"]
            ))
    return "\n".join(lines)


def option(option_id, publisher, model, version, sku, lifecycle, shape,
           score, route, boundary, cost, **gate_changes):
    record = {
        "id": option_id, "publisher": publisher, "model": model,
        "version": version, "sku": sku, "lifecycle": lifecycle,
        "shape": shape, "fit_score": score, "route_scope": route,
        "data_boundary": boundary, "cost": cost,
    }
    record.update({gate: True for gate in GATES})
    record.update(gate_changes)
    return record


